import org.apache.commons.beanutils.PropertyUtils;
import org.apache.commons.beanutils.ConvertUtils;
import org.apache.commons.beanutils.BeanUtils;
import org.apache.commons.beanutils.ConversionException;
import org.apache.commons.beanutils.PropertyUtilsBean;
import org.apache.commons.beanutils.BeanUtilsBean;

import java.lang.reflect.InvocationTargetException;
import java.util.Map;

public void setProperty(Object bean, String name, Object value)
        throws IllegalAccessException, InvocationTargetException {
    try {
        PropertyUtilsBean propertyUtilsBean = BeanUtilsBean.getInstance().getPropertyUtils();

        // Resolve any nested expression to get the actual target bean
        Object target = bean;
        String finalName = name;
        while (propertyUtilsBean.isNestedProperty(target, finalName)) {
            String next = propertyUtilsBean.next(finalName);
            target = propertyUtilsBean.getProperty(target, finalName);
            if (target == null) {
                return;
            }
            finalName = next;
        }

        // Calculate the property type
        Class<?> type = propertyUtilsBean.getPropertyType(target, finalName);

        // Convert the specified value to the required type
        Object newValue = ConvertUtils.convert(value, type);

        // Invoke the setter method
        try {
            PropertyUtils.setSimpleProperty(target, finalName, newValue);
        } catch (NoSuchMethodException e) {
            throw new InvocationTargetException(e, "Cannot set " + finalName);
        }
    } catch (IllegalAccessException e) {
        throw e;
    } catch (InvocationTargetException e) {
        throw e;
    } catch (ConversionException e) {
        throw new InvocationTargetException(e, "Conversion failed for property: " + name);
    } catch (Exception e) {
        throw new InvocationTargetException(e, "Error setting property: " + name);
    }
}

